import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Spec Kit","description":"","frontmatter":{},"headers":[],"relativePath":"agents/spec-kit.md","filePath":"agents/spec-kit.md"}'),o={name:"agents/spec-kit.md"};function i(d,e,c,r,p,l){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="spec-kit" tabindex="-1">Spec Kit <a class="header-anchor" href="#spec-kit" aria-label="Permalink to &quot;Spec Kit&quot;">​</a></h1><p>A repository planned with <a href="https://github.com/github/spec-kit" target="_blank" rel="noreferrer">GitHub Spec Kit</a> keeps a <code>.specify/</code> directory and one directory per feature under <code>specs/</code>. It needs no OpenSpec.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p>Install Spec Kit and set it up in the repository as <a href="https://github.com/github/spec-kit" target="_blank" rel="noreferrer">its README</a> explains. <code>wake init</code> then finds <code>.specify/</code> and records Spec Kit as the plan. When the repository also has OpenSpec, OpenSpec wins unless you run <code>wake init --plan spec-kit</code>.</p><h2 id="planning-with-your-agent" tabindex="-1">Planning with your agent <a class="header-anchor" href="#planning-with-your-agent" aria-label="Permalink to &quot;Planning with your agent&quot;">​</a></h2><p>Ask your agent for a new feature, or run its plan command (such as <code>/wake:plan &lt;idea&gt;</code> in Claude Code). Its <code>wake-planning</code> skill plans the feature with <code>/speckit.specify</code>, <code>/speckit.plan</code> and <code>/speckit.tasks</code>. Milestones live in <code>specs/milestones.yaml</code>, in the <a href="/wake-dist/docs/agents/milestones#group-changes-into-milestones">milestones format</a>, with feature directory names under <code>changes</code>. <code>wake watch</code> syncs on every change under <code>specs/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.specify/</span></span>
<span class="line"><span>specs/</span></span>
<span class="line"><span>  001-user-auth/</span></span>
<span class="line"><span>    spec.md</span></span>
<span class="line"><span>    tasks.md        # - [X] T001 Create project structure</span></span>
<span class="line"><span>                    # - [ ] T002 [P] [US1] Create User model in src/models/user.py</span></span>
<span class="line"><span>  002-billing/</span></span>
<span class="line"><span>    tasks.md</span></span>
<span class="line"><span>  milestones.yaml   # optional; changes: [001-user-auth, 002-billing]</span></span></code></pre></div><h2 id="how-wake-reads-features-and-tasks" tabindex="-1">How Wake reads features and tasks <a class="header-anchor" href="#how-wake-reads-features-and-tasks" aria-label="Permalink to &quot;How Wake reads features and tasks&quot;">​</a></h2><p>Wake reads every <code>specs/&lt;feature&gt;/tasks.md</code> that <code>/speckit.tasks</code> wrote. Each feature directory is a phase (its name lowercased), ordered by the commit that first added a file to it; a feature with only <code>spec.md</code> or <code>plan.md</code> has no phase yet. Each checkbox line with a task id is a task: <code>T002</code> is its number, <code>Create User model in src/models/user.py</code> its title (the <code>[P]</code> and <code>[USn]</code> tags are dropped) and <code>[x]</code> or <code>[X]</code> marks it done. Headings such as <code>## Phase 3: User Story 1</code>, <code>**Checkpoint**</code> lines and fenced examples are ignored. A checkbox without a task id, or a task id used twice in one file, is an error printed as <code>path:line: message</code>, and nothing is sent.</p><p>Wake never writes into Spec Kit files. A task&#39;s id is derived from its feature and its task id, the same on every machine, so regenerating <code>tasks.md</code> keeps the identity of every task whose id stayed (a reworded <code>T003</code> shows up as renamed); a trailing <code>&lt;!-- wake:&lt;id&gt; --&gt;</code> marker, if you add one, wins.</p>`,10)])])}const k=a(o,[["render",i]]);export{u as __pageData,k as default};
